/**
 * src/shapes/edges.css is generated by scripts/generate-shape-edges.mjs
 * (16 start/end pairs + RTL variants). Fails when someone hand-edits the CSS
 * or changes the generator without regenerating.
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { renderShapeEdgesCss } from '../../scripts/generate-shape-edges.mjs';

const file = readFileSync(resolve(import.meta.dirname, '../../src/shapes/edges.css'), 'utf8');

test('edges.css matches the generator (run npm run generate:shape-edges)', () => {
  assert.equal(file, renderShapeEdgesCss());
});

test('every start/end pair has its own composed rule', () => {
  const shapes = ['wave', 'chevron', 'scallop', 'diagonal'];
  for (const s of shapes) for (const e of shapes) {
    assert.ok(file.includes(`[data-shape-start="${s}"][data-shape-end="${e}"] {`), `${s} + ${e}`);
  }
});
